import sys
import time

INF=100000
MATE=30000
VALUE={'p':100,'n':320,'b':330,'r':500,'q':900,'k':20000}
PROMOTION=('','n','b','r','q')

class Position:
    __slots__=('board','turn','rights','ep','half','full')
    def __init__(self,board,turn,rights,ep,half,full):
        self.board=tuple(board)
        self.turn=turn
        self.rights=rights
        self.ep=ep
        self.half=half
        self.full=full
    @classmethod
    def start(cls):
        return cls.from_fen('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1')
    @classmethod
    def from_fen(cls,text):
        a=text.split()
        b=['.']*64
        for row,line in enumerate(a[0].split('/')):
            sq=(7-row)*8
            for ch in line:
                if ch.isdigit():
                    sq+=int(ch)
                else:
                    b[sq]=ch
                    sq+=1
        rights=0
        for i,ch in enumerate('KQkq'):
            if ch in a[2]:
                rights|=1<<i
        ep=-1
        if a[3]!='-':
            ep=(ord(a[3][0])-97)+8*(int(a[3][1])-1)
        return cls(b,0 if a[1]=='w' else 1,rights,ep,int(a[4]),int(a[5]))

def encode(src,dst,promo=0,flags=0):
    return src|(dst<<6)|(promo<<12)|(flags<<16)

def king_square(p,side):
    target='K' if side==0 else 'k'
    for i,ch in enumerate(p.board):
        if ch==target:
            return i
    return -1

def attacked(p,sq,by):
    if sq<0:
        return True
    b=p.board
    r,f=divmod(sq,8)
    pawn='P' if by==0 else 'p'
    pr=r-1 if by==0 else r+1
    if 0<=pr<8:
        for pf in (f-1,f+1):
            if 0<=pf<8 and b[pr*8+pf]==pawn:
                return True
    knight='N' if by==0 else 'n'
    for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
        rr,ff=r+dr,f+df
        if 0<=rr<8 and 0<=ff<8 and b[rr*8+ff]==knight:
            return True
    royal='K' if by==0 else 'k'
    for dr in (-1,0,1):
        for df in (-1,0,1):
            if dr or df:
                rr,ff=r+dr,f+df
                if 0<=rr<8 and 0<=ff<8 and b[rr*8+ff]==royal:
                    return True
    for dr,df,types in ((1,0,'rq'),(-1,0,'rq'),(0,1,'rq'),(0,-1,'rq'),(1,1,'bq'),(1,-1,'bq'),(-1,1,'bq'),(-1,-1,'bq')):
        rr,ff=r+dr,f+df
        while 0<=rr<8 and 0<=ff<8:
            ch=b[rr*8+ff]
            if ch!='.':
                if ch.isupper()==(by==0) and ch.lower() in types:
                    return True
                break
            rr+=dr
            ff+=df
    return False

def in_check(p,side=None):
    if side is None:
        side=p.turn
    return attacked(p,king_square(p,side),side^1)

def pseudo_moves(p,captures_only=False):
    b=p.board
    white=p.turn==0
    out=[]
    def add(a,z,pr=0,fl=0,cap=False):
        if not captures_only or cap or pr:
            out.append(encode(a,z,pr,fl))
    for s,pc in enumerate(b):
        if pc=='.' or pc.isupper()!=white:
            continue
        r,f=divmod(s,8)
        typ=pc.lower()
        if typ=='p':
            step=8 if white else -8
            z=s+step
            last=7 if white else 0
            if 0<=z<64 and b[z]=='.':
                if z//8==last:
                    for pr in (4,3,2,1):
                        add(s,z,pr)
                else:
                    add(s,z)
                    if not captures_only and r==(1 if white else 6) and b[s+2*step]=='.':
                        add(s,s+2*step,0,4)
            for df in (-1,1):
                ff=f+df
                if not 0<=ff<8:
                    continue
                z=s+step+df
                if not 0<=z<64:
                    continue
                target=b[z]
                enemy=target!='.' and target.isupper()!=white and target.lower()!='k'
                if enemy:
                    if z//8==last:
                        for pr in (4,3,2,1):
                            add(s,z,pr,0,True)
                    else:
                        add(s,z,0,0,True)
                elif z==p.ep and target=='.':
                    behind=z-8 if white else z+8
                    if 0<=behind<64 and b[behind]==('p' if white else 'P'):
                        add(s,z,0,1,True)
        elif typ=='n':
            for dr,df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
                rr,ff=r+dr,f+df
                if 0<=rr<8 and 0<=ff<8:
                    z=rr*8+ff
                    if b[z]=='.':
                        add(s,z)
                    elif b[z].isupper()!=white and b[z].lower()!='k':
                        add(s,z,0,0,True)
        elif typ in 'brq':
            directions=[]
            if typ in 'bq':
                directions += ((1,1),(1,-1),(-1,1),(-1,-1))
            if typ in 'rq':
                directions += ((1,0),(-1,0),(0,1),(0,-1))
            for dr,df in directions:
                rr,ff=r+dr,f+df
                while 0<=rr<8 and 0<=ff<8:
                    z=rr*8+ff
                    if b[z]=='.':
                        add(s,z)
                    else:
                        if b[z].isupper()!=white and b[z].lower()!='k':
                            add(s,z,0,0,True)
                        break
                    rr+=dr
                    ff+=df
        else:
            for dr in (-1,0,1):
                for df in (-1,0,1):
                    if dr or df:
                        rr,ff=r+dr,f+df
                        if 0<=rr<8 and 0<=ff<8:
                            z=rr*8+ff
                            if b[z]=='.':
                                add(s,z)
                            elif b[z].isupper()!=white and b[z].lower()!='k':
                                add(s,z,0,0,True)
            if not captures_only and s==(4 if white else 60) and not attacked(p,s,p.turn^1):
                if white and p.rights&1 and b[5]==b[6]=='.' and b[7]=='R' and not attacked(p,5,1) and not attacked(p,6,1):
                    add(s,6,0,2)
                if white and p.rights&2 and b[1]==b[2]==b[3]=='.' and b[0]=='R' and not attacked(p,3,1) and not attacked(p,2,1):
                    add(s,2,0,2)
                if not white and p.rights&4 and b[61]==b[62]=='.' and b[63]=='r' and not attacked(p,61,0) and not attacked(p,62,0):
                    add(s,62,0,2)
                if not white and p.rights&8 and b[57]==b[58]==b[59]=='.' and b[56]=='r' and not attacked(p,59,0) and not attacked(p,58,0):
                    add(s,58,0,2)
    return out

def apply_move(p,m):
    src=m&63
    dst=(m>>6)&63
    promo=(m>>12)&15
    flags=m>>16
    b=list(p.board)
    pc=b[src]
    captured=b[dst]
    b[src]='.'
    if flags&1:
        ep_sq=dst-8 if pc.isupper() else dst+8
        captured=b[ep_sq]
        b[ep_sq]='.'
    b[dst]=pc
    if flags&2:
        if dst==6:
            b[5]=b[7]; b[7]='.'
        elif dst==2:
            b[3]=b[0]; b[0]='.'
        elif dst==62:
            b[61]=b[63]; b[63]='.'
        elif dst==58:
            b[59]=b[56]; b[56]='.'
    if promo:
        b[dst]=('NBRQ'[promo-1] if pc.isupper() else 'nbrq'[promo-1])
    rights=p.rights
    if pc=='K': rights&=~3
    if pc=='k': rights&=~12
    for sq,mask in ((0,2),(7,1),(56,8),(63,4)):
        if src==sq or dst==sq:
            rights&=~mask
    ep=(src+dst)//2 if pc.lower()=='p' and abs(dst-src)==16 else -1
    half=0 if pc.lower()=='p' or captured!='.' else p.half+1
    full=p.full+(1 if p.turn else 0)
    return Position(b,p.turn^1,rights,ep,half,full)

def legal_moves(p,captures_only=False):
    result=[]
    side=p.turn
    for m in pseudo_moves(p,captures_only):
        q=apply_move(p,m)
        if not in_check(q,side):
            result.append(m)
    return result

def uci_move(m):
    a=m&63
    z=(m>>6)&63
    pr=(m>>12)&15
    return 'abcdefgh'[a&7]+str(a//8+1)+'abcdefgh'[z&7]+str(z//8+1)+(PROMOTION[pr] if pr else '')

class Engine:
    def __init__(self):
        self.pos=Position.start()
        self.tt={}
        self.history={}
        self.killers={}
        self.nodes=0
        self.deadline=0.0
        self.root_hint=-1
    def evaluate(self,p):
        b=p.board
        score=0
        nonpawn=0
        wp=[0]*8
        bp=[0]*8
        wb=bb=0
        for ch in b:
            if ch!='.' and ch.lower() not in 'pk':
                nonpawn+=VALUE[ch.lower()]
        for s,ch in enumerate(b):
            if ch=='.':
                continue
            typ=ch.lower()
            sign=1 if ch.isupper() else -1
            r,f=divmod(s,8)
            rr=r if sign==1 else 7-r
            center=max(0,14-abs(2*f-7)-abs(2*rr-7))
            if typ=='p':
                score+=sign*(100+rr*8+center*2)
                (wp if sign==1 else bp)[f]+=1
            elif typ=='n':
                score+=sign*(320+center*7-(4 if f in (0,7) else 0))
            elif typ=='b':
                score+=sign*(330+center*4)
                if sign==1: wb+=1
                else: bb+=1
            elif typ=='r':
                score+=sign*(500+rr*4+(12 if (wp if sign==1 else bp)[f]==0 else 0))
            elif typ=='q':
                score+=sign*(900+center*2)
            else:
                if nonpawn<1800:
                    score+=sign*(20000+center*9)
                else:
                    score+=sign*(20000-center*4)
        if wb>=2: score+=32
        if bb>=2: score-=32
        for f,n in enumerate(wp):
            if n>1: score-=10*(n-1)
            if n and (f==0 or wp[f-1]==0) and (f==7 or wp[f+1]==0): score-=8*n
        for f,n in enumerate(bp):
            if n>1: score+=10*(n-1)
            if n and (f==0 or bp[f-1]==0) and (f==7 or bp[f+1]==0): score+=8*n
        for s,ch in enumerate(b):
            if ch.lower()!='p':
                continue
            sign=1 if ch.isupper() else -1
            r,f=divmod(s,8)
            enemy='p' if sign==1 else 'P'
            passed=True
            ranks=range(r+1,8) if sign==1 else range(r-1,-1,-1)
            for rr in ranks:
                for ff in (f-1,f,f+1):
                    if 0<=ff<8 and b[rr*8+ff]==enemy:
                        passed=False
            if passed:
                score+=sign*(18+(r if sign==1 else 7-r)*9)
        return score if p.turn==0 else -score
    def tick(self):
        self.nodes+=1
        if self.nodes&15==0 and time.perf_counter()>=self.deadline:
            raise TimeoutError
    def move_score(self,p,m,ttmove=-1,ply=0):
        src=m&63
        dst=(m>>6)&63
        promo=(m>>12)&15
        flags=m>>16
        score=0
        if m==ttmove: score+=10000000
        victim=p.board[dst]
        if flags&1: victim='p'
        if victim!='.': score+=1000000+VALUE[victim.lower()]*12-VALUE[p.board[src].lower()]
        if promo: score+=700000+promo*10000
        if flags&2: score+=200
        if self.killers.get(ply)==m: score+=50000
        score+=self.history.get((p.turn,src,dst),0)
        return score
    def qsearch(self,p,alpha,beta,ply):
        self.tick()
        checked=in_check(p)
        if checked:
            stand=-INF
            moves=legal_moves(p)
        else:
            stand=self.evaluate(p)
            if stand>=beta: return stand
            if stand>alpha: alpha=stand
            if ply>=12: return stand
            moves=legal_moves(p,True)
        if not moves:
            return (-MATE+ply) if checked else stand
        moves.sort(key=lambda x:self.move_score(p,x,-1,ply),reverse=True)
        for m in moves:
            value=-self.qsearch(apply_move(p,m),-beta,-alpha,ply+1)
            if value>=beta: return value
            if value>alpha: alpha=value
        return alpha
    def search(self,p,depth,alpha,beta,ply):
        self.tick()
        moves=legal_moves(p)
        if not moves:
            return -MATE+ply if in_check(p) else 0
        if p.half>=100:
            return 0
        if depth<=0:
            return self.qsearch(p,alpha,beta,ply)
        alpha0=alpha
        beta0=beta
        key=(p.board,p.turn,p.rights,p.ep,p.half)
        entry=self.tt.get(key)
        ttmove=-1
        if entry:
            ed,stored,flag,ttmove=entry
            value=stored
            if value>MATE-1000: value-=ply
            elif value<-MATE+1000: value+=ply
            if ed>=depth:
                if flag==0: return value
                if flag==1: alpha=max(alpha,value)
                else: beta=min(beta,value)
                if alpha>=beta: return value
        moves.sort(key=lambda x:self.move_score(p,x,ttmove,ply),reverse=True)
        best=-INF
        bestmove=moves[0]
        for m in moves:
            q=apply_move(p,m)
            next_depth=depth-1
            if depth<=2 and in_check(q):
                next_depth+=1
            value=-self.search(q,next_depth,-beta,-alpha,ply+1)
            if value>best:
                best=value
                bestmove=m
            if value>alpha:
                alpha=value
            if alpha>=beta:
                src=m&63
                dst=(m>>6)&63
                if p.board[dst]=='.' and not (m>>12)&15 and not (m>>16)&1:
                    self.killers[ply]=m
                    hkey=(p.turn,src,dst)
                    self.history[hkey]=min(20000,self.history.get(hkey,0)+depth*depth)
                break
        flag=2 if best<=alpha0 else 1 if best>=beta0 else 0
        stored=best
        if stored>MATE-1000: stored+=ply
        elif stored<-MATE+1000: stored-=ply
        self.tt[key]=(depth,stored,flag,bestmove)
        if len(self.tt)>120000:
            self.tt.clear()
        return best
    def root(self,p,moves,depth):
        moves=moves[:]
        moves.sort(key=lambda x:self.move_score(p,x,self.root_hint,0),reverse=True)
        alpha=-INF
        best=-INF
        bestmove=moves[0]
        for i,m in enumerate(moves):
            self.tick()
            q=apply_move(p,m)
            if i==0:
                value=-self.search(q,depth-1,-INF,INF,1)
            else:
                value=-self.search(q,depth-1,-alpha-1,-alpha,1)
                if alpha<value<INF:
                    value=-self.search(q,depth-1,-INF,-alpha,1)
            if value>best:
                best=value
                bestmove=m
            if value>alpha:
                alpha=value
        return best,bestmove
    def think(self,millis):
        self.nodes=0
        self.deadline=time.perf_counter()+max(0.0004,millis*0.00072)
        moves=legal_moves(self.pos)
        if not moves:
            return '0000'
        moves.sort(key=lambda x:self.move_score(self.pos,x,-1,0),reverse=True)
        best=moves[0]
        self.root_hint=best
        if millis<=2:
            return uci_move(best)
        for depth in range(1,64):
            try:
                value,candidate=self.root(self.pos,moves,depth)
                best=candidate
                self.root_hint=best
                if abs(value)>=MATE-100:
                    break
            except TimeoutError:
                break
        return uci_move(best)
    def set_position(self,a):
        try:
            if len(a)>=2 and a[1]=='startpos':
                p=Position.start()
                i=2
            elif len(a)>=8 and a[1]=='fen':
                p=Position.from_fen(' '.join(a[2:8]))
                i=8
            else:
                return
            if i<len(a) and a[i]=='moves':
                for text in a[i+1:]:
                    for m in legal_moves(p):
                        if uci_move(m)==text:
                            p=apply_move(p,m)
                            break
            self.pos=p
        except Exception:
            return

def main():
    e=Engine()
    for line in sys.stdin:
        a=line.strip().split()
        if not a:
            continue
        if a[0]=='uci':
            print('id name CleanRoomPython')
            print('id author Codex')
            print('uciok')
            sys.stdout.flush()
        elif a[0]=='isready':
            print('readyok')
            sys.stdout.flush()
        elif a[0]=='ucinewgame':
            e.tt.clear()
            e.history.clear()
            e.killers.clear()
        elif a[0]=='position':
            e.set_position(a)
        elif a[0]=='go':
            millis=1000
            if 'movetime' in a:
                try:
                    millis=max(1,int(a[a.index('movetime')+1]))
                except Exception:
                    millis=1
            try:
                move=e.think(millis)
            except Exception:
                moves=legal_moves(e.pos)
                move=uci_move(moves[0]) if moves else '0000'
            print('bestmove '+move)
            sys.stdout.flush()
        elif a[0]=='quit':
            break

if __name__=='__main__':
    main()
